// WorkspacesServer is the server API for Workspaces service.
// All implementations must embed UnimplementedWorkspacesServer
// for forward compatibility.
//
// A person's workspaces of a repository, keyed by (repository, caller, workspace name): each its
// own operation log (docs/scm.md, "Decisions", 3), which machine holds its lease, and its
// checkpoints — what its working copy held, moment to moment, outside the operation log
// (docs/okfs.md). Every call is about the caller's own workspaces.
type WorkspacesServer interface {
	// Takes a workspace's lease for a machine. Held by another machine whose lease has not expired,
	// it is refused — or, with takeover, the holder is asked to hand over and the call answers
	// granted = false until it has (or its lease expires); call again.
	Attach(context.Context, *AttachRequest) (*AttachResponse, error)
	// Extends a lease. FAILED_PRECONDITION when the lease is no longer the caller's.
	Renew(context.Context, *RenewRequest) (*RenewResponse, error)
	Release(context.Context, *ReleaseRequest) (*ReleaseResponse, error)
	// Records a checkpoint whose trees the SCM already holds (published first). It becomes the
	// workspace's latest when the caller holds the current lease and its parent is the latest;
	// otherwise it is kept as a fork.
	RecordCheckpoint(context.Context, *RecordCheckpointRequest) (*Checkpoint, error)
	GetCheckpoint(context.Context, *GetCheckpointRequest) (*Checkpoint, error)
	ListCheckpoints(context.Context, *ListCheckpointsRequest) (*ListCheckpointsResponse, error)
	ListWorkspaces(context.Context, *ListWorkspacesRequest) (*ListWorkspacesResponse, error)
	// Makes a workspace of the caller's, with an operation log of its own that holds only the root
	// operation. ALREADY_EXISTS when the caller has a workspace of that name.
	CreateWorkspace(context.Context, *CreateWorkspaceRequest) (*WorkspaceState, error)
	mustEmbedUnimplementedWorkspacesServer()
}

